// Maps the register macros generated by HLS (xtopann_hw.h) to stable names.
// Vivado HLS (<= 2019.x) appends "_V" to ap_fixed ports; Vitis HLS does not.
// The header itself is produced by Vivado/HLS/run_hls.tcl; host tests use
// tests/xtopann_hw_sim.h instead.
#ifndef ANN_REGS_H
#define ANN_REGS_H

#ifndef ANN_REGS_HEADER
#define ANN_REGS_HEADER "xtopann_hw.h"
#endif
#include ANN_REGS_HEADER

#include "model_params.h"

#define ANN_ADDR_AP_CTRL XTOPANN_CTRL_ADDR_AP_CTRL

#if defined(XTOPANN_CTRL_ADDR_INPUTS_V_BASE)
#define ANN_ADDR_INPUTS      XTOPANN_CTRL_ADDR_INPUTS_V_BASE
#define ANN_DEPTH_INPUTS     XTOPANN_CTRL_DEPTH_INPUTS_V
#define ANN_ADDR_W1          XTOPANN_CTRL_ADDR_W1_V_BASE
#define ANN_DEPTH_W1         XTOPANN_CTRL_DEPTH_W1_V
#define ANN_ADDR_B1          XTOPANN_CTRL_ADDR_B1_V_BASE
#define ANN_DEPTH_B1         XTOPANN_CTRL_DEPTH_B1_V
#define ANN_ADDR_W2          XTOPANN_CTRL_ADDR_W2_V_BASE
#define ANN_DEPTH_W2         XTOPANN_CTRL_DEPTH_W2_V
#define ANN_ADDR_B2          XTOPANN_CTRL_ADDR_B2_V_DATA
#define ANN_ADDR_RESULT      XTOPANN_CTRL_ADDR_RESULT_V_DATA
#elif defined(XTOPANN_CTRL_ADDR_INPUTS_BASE)
#define ANN_ADDR_INPUTS      XTOPANN_CTRL_ADDR_INPUTS_BASE
#define ANN_DEPTH_INPUTS     XTOPANN_CTRL_DEPTH_INPUTS
#define ANN_ADDR_W1          XTOPANN_CTRL_ADDR_W1_BASE
#define ANN_DEPTH_W1         XTOPANN_CTRL_DEPTH_W1
#define ANN_ADDR_B1          XTOPANN_CTRL_ADDR_B1_BASE
#define ANN_DEPTH_B1         XTOPANN_CTRL_DEPTH_B1
#define ANN_ADDR_W2          XTOPANN_CTRL_ADDR_W2_BASE
#define ANN_DEPTH_W2         XTOPANN_CTRL_DEPTH_W2
#define ANN_ADDR_B2          XTOPANN_CTRL_ADDR_B2_DATA
#define ANN_ADDR_RESULT      XTOPANN_CTRL_ADDR_RESULT_DATA
#else
#error "xtopann_hw.h is not the header of the new topann IP (bundle CTRL). Run Vivado/HLS/run_hls.tcl, which copies the generated header here."
#endif

// Catch a stale header from a model with a different size at compile time.
static_assert(ANN_DEPTH_INPUTS == N_IN, "xtopann_hw.h was generated for a different N_IN; re-run run_hls.tcl");
static_assert(ANN_DEPTH_W1 == H_HID * N_IN, "xtopann_hw.h was generated for a different H_HID*N_IN");
static_assert(ANN_DEPTH_B1 == H_HID, "xtopann_hw.h was generated for a different H_HID");
static_assert(ANN_DEPTH_W2 == H_HID, "xtopann_hw.h was generated for a different H_HID");

// ap_ctrl bits
#define ANN_AP_START 0x1u
#define ANN_AP_DONE  0x2u   // clear on read
#define ANN_AP_IDLE  0x4u

#endif
